import re,json,math
def identity(text):
 rows=[line for line in text.splitlines() if line.startswith('node_exporter_build_info{')]
 if len(rows)!=1:raise ValueError('exactly one exporter build sample required')
 match=re.fullmatch(r'node_exporter_build_info\{(.*)\}\s+(\S+)',rows[0])
 if match is None or float(match[2])!=1:raise ValueError('build info marker must be one')
 fields={key:json.loads('"'+value+'"') for key,value in re.findall(r'([a-zA-Z_][a-zA-Z0-9_]*)="((?:[^"\\]|\\.)*)"',match[1])}
 if not all(fields.get(key) for key in ('version','revision','goversion')):raise ValueError('required identity labels missing')
 return {key:fields[key] for key in ('version','revision','goversion')}
```

原题知识说明：
版本、修订和构建信息通常作为标签，样本值通常为1，用于存在性和元信息关联。不要对其数值求平均来计算版本；应按标签盘点并控制关联匹配唯一性。

