import re,os,stat
from pathlib import Path
def retire_job(directory,job):
 if not isinstance(job,str) or re.fullmatch(r'[A-Za-z][A-Za-z0-9_-]{0,63}',job) is None:raise ValueError('exact simple job identifier required')
 target=Path(directory)/(job+'.prom')
 try:info=target.lstat()
 except FileNotFoundError:return False
 if not stat.S_ISREG(info.st_mode):raise ValueError('only owned regular metric file may be retired')
 target.unlink();return True
```

